// Un mes de informes inventados (de hace 30 días a hoy), siempre iguales para una misma fecha.
// Los de hoy llevan su hora de fin de turno: la API solo enseña los turnos que ya han terminado.
const rng = (semilla) => () => {
  semilla = (semilla + 0x6D2B79F5) | 0;
  let t = Math.imul(semilla ^ (semilla >>> 15), 1 | semilla);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const LINEAS = [
  { n: 'Perfiladora 1', obj: 5000, ops: ['Marta Soler', 'Iván Ruiz', 'Carlos Vidal'], formato: 0.25 },
  { n: 'Perfiladora 2', obj: 4000, ops: ['Laura Gómez', 'Raúl Peña', 'Sergio Mata'], formato: 0.5 },
  { n: 'Cizalla', obj: 4000, ops: ['Nuria Ferrer', 'Hugo Ortiz', 'Pablo Cano'], formato: 0.15 },
];
const TURNOS = [['Mañana', 14], ['Tarde', 22], ['Noche', 6]];
const entre = (r, a, b) => Math.round(a + r() * (b - a));
const OBS = {
  'Avería': ['Avería en el motor principal; avisado mantenimiento.', 'Rodamiento del rodillo caliente; se cambia en el siguiente paro.', 'Fallo de sensor de final de carrera.'],
  'Cambio de formato': ['Dos cambios de formato por pedidos pequeños.', 'Cambio de formato más largo de lo previsto.'],
  'Falta de material': ['Llegó tarde la bobina del pedido urgente.', 'Se acabó la bobina y hubo que esperar la siguiente.'],
  'Otros': ['Parada breve por limpieza de la línea.', 'Reunión de seguridad al inicio del turno.'],
};

const filas = [];
for (let dia = 30; dia >= 0; dia--) {
  const dt = hoy.minus({ days: dia });
  if (dt.weekday === 7) continue;
  LINEAS.forEach((l, li) => {
    TURNOS.forEach(([turno, horaFin], ti) => {
      if (dt.weekday === 6 && turno === 'Noche') return;
      const r = rng(dia * 977 + li * 131 + ti * 17 + 12345);
      // Historia: una racha de averías en la cizalla de noche y de tarde hace dos semanas.
      const racha = l.n === 'Cizalla' && dia >= 12 && dia <= 16 && turno !== 'Mañana';
      const averia = racha ? entre(r, 55, 110) : (r() < 0.12 ? entre(r, 15, 50) : 0);
      const formato = r() < l.formato ? entre(r, 12, 40) : 0;
      const material = r() < (turno === 'Tarde' ? 0.16 : 0.08) ? entre(r, 10, 40) : 0;
      const otros = r() < 0.15 ? entre(r, 5, 20) : 0;
      const total = averia + formato + material + otros;
      let metros = Math.round(l.obj * (1 - (total / 480) * 1.6) * (0.9 + r() * 0.1));
      metros = Math.max(0, Math.min(metros, Math.round(l.obj * 1.03)));
      const eficiencia = Math.round((metros / l.obj) * 1000) / 10;
      const paradas = { 'Avería': averia, 'Cambio de formato': formato, 'Falta de material': material, 'Otros': otros };
      const [motivo, minutos] = Object.entries(paradas).sort((a, b) => b[1] - a[1])[0];
      const opciones = OBS[motivo];
      filas.push({ json: {
        sid: 'demo', fecha: dt.toFormat('yyyy-MM-dd'), turno, linea: l.n, operario: l.ops[ti],
        metros, objetivo: l.obj, eficiencia,
        parada_averia: averia, parada_cambio_formato: formato, parada_falta_material: material, parada_otros: otros,
        paradas_total: total, motivo_principal: minutos > 0 ? motivo : 'Sin paradas',
        aviso: eficiencia < 80,
        observaciones: minutos >= 25 ? opciones[entre(r, 0, opciones.length - 1)] : '',
        registrado_en: dt.set({ hour: horaFin, minute: entre(r, 0, 20) }).toISO(),
        creado_ms: 0,
      } });
    });
  });
}
return filas;

// Solicitudes de compañeros inventados, con fechas relativas a hoy y siempre las mismas para un mismo día.
// Son comunes a todos los visitantes y de solo lectura. Ninguno es un empleado que el visitante pueda elegir.
const FESTIVOS = ['01-01', '01-06', '05-01', '08-15', '10-12', '11-01', '12-06', '12-08', '12-25'];
const VIERNES_SANTO = ['2026-04-03', '2027-03-26'];
const laborable = (d) => d.weekday < 6 && !FESTIVOS.includes(d.toFormat('MM-dd')) && !VIERNES_SANTO.includes(d.toFormat('yyyy-MM-dd'));
const contar = (a, z) => { let n = 0; for (let d = a; d <= z; d = d.plus({ days: 1 })) if (laborable(d)) n++; return n; };

// El lunes de la semana que viene no, la siguiente: la página propone por defecto unas fechas que coinciden con Iván Ruiz.
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const base = hoy.plus({ days: (8 - hoy.weekday) + 7 });
const PLANTILLA = [
  // empleado, departamento, tipo, estado, días desde la base (inicio, fin), pedida hace N días, saldo previo
  ['Raúl Peña', 'Producción', 'Asuntos propios', 'Aprobada', -14, -14, 12, 18],
  ['Iván Ruiz', 'Producción', 'Vacaciones', 'Aprobada', 0, 4, 9, 22],
  ['Andrés Gil', 'Comercial', 'Permiso retribuido', 'Pendiente', 1, 1, 1, 15],
  ['Lucía Prieto', 'Administración', 'Vacaciones', 'Rechazada', 2, 6, 6, 20],
  ['Carmen Vidal', 'Administración', 'Asuntos propios', 'Pendiente', 3, 3, 2, 17],
  ['Sergio Mata', 'Logística', 'Vacaciones', 'Aprobada', 7, 11, 8, 22],
  ['Elena Martín', 'Calidad', 'Vacaciones', 'Aprobada', 14, 18, 5, 19],
  ['Óscar Lara', 'Logística', 'Vacaciones', 'Pendiente', 21, 25, 0, 22],
];
const filas = PLANTILLA.map(([empleado, departamento, tipo, estado, a, z, hace, saldo], i) => {
  const desde = base.plus({ days: a });
  const hasta = base.plus({ days: z });
  const pedida = hoy.minus({ days: hace }).set({ hour: 8 + i, minute: (i * 17) % 60 });
  return {
    sid: 'demo', fecha_solicitud: pedida.toFormat('yyyy-MM-dd HH:mm'), empleado, departamento, tipo,
    desde: desde.toFormat('yyyy-MM-dd'), hasta: hasta.toFormat('yyyy-MM-dd'), dias: contar(desde, hasta),
    saldo_previo: saldo, estado, comentario: '', conflictos: '',
    decidido_en: estado === 'Pendiente' ? '' : pedida.plus({ hours: 26 }).toFormat('yyyy-MM-dd HH:mm'),
    creado_ms: 0,
  };
}).filter((r) => r.dias > 0);
// Coincidencias con el resto del departamento, como las calcularía el flujo real.
for (const r of filas) {
  r.conflictos = filas
    .filter((o) => o !== r && o.departamento === r.departamento && o.estado !== 'Rechazada' && o.desde <= r.hasta && o.hasta >= r.desde)
    .map((o) => `${o.empleado} (${o.desde} a ${o.hasta}, ${o.estado.toLowerCase()})`)
    .join('; ');
}
return filas.map((json) => ({ json }));

// Datos maestros inventados: fichas de proveedor (con la cuenta bancaria registrada) y pedidos de compra.
const PROVEEDORES = {
  B48123456: { nombre: 'Aceros del Norte, S.L.', iban: 'ES9121000418450200051332', plazo: 60 },
  A46234567: { nombre: 'Bobinas Levante, S.A.', iban: 'ES6000491500051234567892', plazo: 60 },
  B50345678: { nombre: 'Transportes Ebro, S.L.', iban: 'ES1720852066623456789011', plazo: 30 },
  B28456789: { nombre: 'Suministros Industriales Gil, S.L.', iban: 'ES3001820815200201234567', plazo: 30 },
  B26567890: { nombre: 'Mantenimiento Técnico Arnedo, S.L.', iban: 'ES4521003915102200123456', plazo: 30 },
};
// Proveedores que pueden enviar facturas pero no tienen ficha (no están dados de alta).
const SIN_FICHA = { B31678901: 'Talleres Ribera, S.L.' };
const PEDIDOS = {
  'PC-2026-0412': { nif: 'B48123456', concepto: 'Bobina de acero galvanizado 1,5 mm (12 t)', base: 10680 },
  'PC-2026-0415': { nif: 'A46234567', concepto: 'Bobina prelacada RAL 9002 (8 t)', base: 9120 },
  'PC-2026-0418': { nif: 'B50345678', concepto: 'Portes de octubre (14 viajes)', base: 2380 },
  'PC-2026-0421': { nif: 'B28456789', concepto: 'EPIs y guantes anticorte', base: 845.6 },
  'PC-2026-0423': { nif: 'B26567890', concepto: 'Cambio de rodamientos de la Perfiladora 2', base: 1940 },
  'PC-2026-0426': { nif: 'B48123456', concepto: 'Fleje de acero 0,8 mm (5 t)', base: 4350 },
  'PC-2026-0427': { nif: 'B48123456', concepto: 'Chapa lisa 2 mm (3 t)', base: 2910 },
  'PC-2026-0430': { nif: 'B28456789', concepto: 'Juego de cuchillas para la cizalla', base: 1275 },
};
const DIA_MS = 24 * 3600 * 1000;
const r2 = (n) => Math.round(n * 100) / 100;
const eur = (n) => Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const limpiaIban = (s) => String(s ?? '').replace(/\s+/g, '').toUpperCase();
const isoD = (d) => d.toISOString().slice(0, 10);
const nombreDe = (nif) => PROVEEDORES[nif]?.nombre ?? SIN_FICHA[nif] ?? `Proveedor ${nif}`;

// Vence a los días de plazo de la ficha (30 si no hay ficha) y se paga en la primera remesa (día 10 o 25) desde
// el vencimiento, o desde hoy si el vencimiento ya pasó.
function plazos(fecha, nif, hoy) {
  const v = new Date(Date.parse(fecha + 'T00:00:00Z') + (PROVEEDORES[nif]?.plazo ?? 30) * DIA_MS);
  let d = new Date(Math.max(v.getTime(), Date.parse(hoy + 'T00:00:00Z')));
  while (![10, 25].includes(d.getUTCDate())) d = new Date(d.getTime() + DIA_MS);
  return { vencimiento: isoD(v), fecha_pago: isoD(d) };
}

// Las cinco comprobaciones de contabilidad. `otras` son las facturas ya registradas que ve este visitante.
function comprobar(f, otras) {
  const p = PROVEEDORES[f.nif];
  const c = [];
  c.push({ nombre: 'Proveedor dado de alta', ok: !!p, detalle: p ? `${p.nombre} (${f.nif})` : `${nombreDe(f.nif)} (${f.nif}) no tiene ficha de proveedor` });

  const esperado = r2(f.base * (1 + f.iva_pct / 100));
  const cuadra = Math.abs(esperado - f.total) < 0.011;
  c.push({ nombre: 'Base + IVA = total', ok: cuadra, detalle: cuadra
    ? `${eur(f.base)} + ${f.iva_pct} % de IVA = ${eur(f.total)}`
    : `${eur(f.base)} + ${f.iva_pct} % de IVA son ${eur(esperado)}, y la factura dice ${eur(f.total)}` });

  const clave = (s) => String(s).trim().toUpperCase();
  const dup = otras.find((o) => o.nif === f.nif && clave(o.numero) === clave(f.numero));
  c.push({ nombre: 'No está duplicada', ok: !dup, detalle: dup
    ? `La factura ${dup.numero} de este proveedor ya se registró el ${dup.fecha} (${String(dup.estado).toLowerCase()})`
    : 'Número nuevo para este proveedor' });

  const ped = PEDIDOS[f.pedido];
  let okPed = false;
  let detPed;
  if (!f.pedido) detPed = 'La factura no indica ningún pedido de compra';
  else if (!ped || ped.nif !== f.nif) detPed = `El pedido ${f.pedido} no es de este proveedor`;
  else {
    const usada = otras.find((o) => o.pedido === f.pedido && o.estado !== 'Rechazada');
    const dif = r2(f.base - ped.base);
    if (usada) detPed = `El pedido ${f.pedido} ya se facturó con la ${usada.numero}`;
    else if (Math.abs(dif) > Math.max(1, ped.base * 0.005)) detPed = `El pedido ${f.pedido} es de ${eur(ped.base)} y la factura cobra ${eur(Math.abs(dif))} de ${dif > 0 ? 'más' : 'menos'}`;
    else { okPed = true; detPed = `Pedido ${f.pedido}: ${ped.concepto}`; }
  }
  c.push({ nombre: 'Coincide con el pedido', ok: okPed, detalle: detPed });

  const iban = limpiaIban(f.iban);
  const okIban = !!p && iban === p.iban;
  c.push({ nombre: 'Cuenta bancaria de la ficha', ok: okIban, detalle: !p
    ? 'No hay ficha con la que comparar la cuenta'
    : okIban ? `La cuenta termina en ${p.iban.slice(-4)}, como en la ficha`
      : `Pide el pago en una cuenta que termina en ${iban.slice(-4)} y la ficha dice ${p.iban.slice(-4)}: confirmar por teléfono antes de pagar` });
  return c;
}

// Un mes de facturas recibidas, con fechas relativas a hoy y siempre las mismas para un mismo día.
// Son comunes a todos los visitantes y de solo lectura. Pasan por las mismas comprobaciones que las del visitante.
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const LIBRO = [
  // nif, número, hace N días, pedido, base, IVA, cuenta (si no es la de la ficha), decisión de contabilidad
  ['B48123456', 'A-2026/1123', 28, 'PC-2026-0412', 10680, 21],
  ['A46234567', 'FV-26/0877', 21, 'PC-2026-0415', 9120, 21],
  ['B50345678', '2026-0311', 15, 'PC-2026-0418', 2420, 21, null, 'pagar'],
  ['B28456789', 'G-4410', 9, 'PC-2026-0421', 845.6, 21],
  ['B48123456', 'A-2026/1190', 4, 'PC-2026-0427', 2910, 21, 'ES7601822370420201234561', 'rechazar'],
  ['B31678901', 'TR-118', 2, '', 380, 21, 'ES2830350012120123456789'],
];
const filas = [];
LIBRO.forEach(([nif, numero, hace, pedido, base, iva_pct, cuenta, decision], i) => {
  const dt = hoy.minus({ days: hace });
  const fecha = dt.toFormat('yyyy-MM-dd');
  const total = r2(base * (1 + iva_pct / 100));
  const iban = cuenta ?? PROVEEDORES[nif].iban;
  const comprobaciones = comprobar({ nif, numero, pedido, base, iva_pct, total, iban }, filas);
  const fallos = comprobaciones.filter((c) => !c.ok);
  let estado = fallos.length ? 'Pendiente de revisar' : 'Contabilizada';
  let decidido_en = '';
  if (fallos.length && decision) {
    estado = decision === 'pagar' ? 'Contabilizada' : 'Rechazada';
    decidido_en = dt.plus({ days: 1 }).set({ hour: 9 + i, minute: 30 }).toFormat('yyyy-MM-dd HH:mm');
  }
  const p = plazos(fecha, nif, fecha);
  filas.push({
    sid: 'demo', proveedor: nombreDe(nif), nif, numero, fecha, pedido, concepto: PEDIDOS[pedido]?.concepto ?? 'Sin pedido',
    base, iva_pct, cuota_iva: r2(total - base), total, iban,
    vencimiento: p.vencimiento, fecha_pago: estado === 'Contabilizada' ? p.fecha_pago : '',
    estado, incidencias: fallos.map((c) => c.detalle).join('; '),
    comprobaciones: JSON.stringify(comprobaciones), decidido_en, creado_ms: 0,
  });
});
return filas.map((json) => ({ json }));

// Reglas fijas de puntuación (sin IA) y reparto por zonas. Datos inventados.
const PRODUCTOS = { 'Perfiles para pladur': 40, 'Chapa perfilada para cubiertas': 40, 'Fleje de acero': 30, 'Corte a medida': 25, 'Otro producto': 0 };
const VOLUMENES = { 'Menos de 1.000 m al mes': 5, 'De 1.000 a 10.000 m al mes': 20, 'Más de 10.000 m al mes': 30 };
const PLAZOS = { 'Urgente (menos de 2 semanas)': 20, 'Este trimestre': 12, 'Solo pido información': 3 };
const SECTORES = { 'Construcción': 10, 'Estructuras metálicas': 10, 'Naves agrícolas': 8, 'Distribución de materiales': 8, 'Otro': 4 };
const ZONAS = {
  Norte: { comercial: 'Iker Zubia', provincias: ['Asturias', 'Bizkaia', 'Cantabria', 'Gipuzkoa', 'La Rioja', 'Navarra'] },
  Este: { comercial: 'Laia Puig', provincias: ['Barcelona', 'Castellón', 'Tarragona', 'Valencia', 'Zaragoza'] },
  'Centro y Sur': { comercial: 'Javier Ortega', provincias: ['Córdoba', 'Madrid', 'Málaga', 'Sevilla', 'Toledo', 'Valladolid'] },
};
const zonaDe = (provincia) => Object.entries(ZONAS).find(([, z]) => z.provincias.includes(provincia));
const ABIERTOS = ['Nuevo', 'Recordatorio enviado'];

// Puntos de 0 a 100 y temperatura. Caliente: llamar en 24 h. Templado: en 3 días. Frío: al boletín, sin llamada.
function puntuar(l) {
  const desglose = [
    { criterio: 'Producto', valor: l.producto, puntos: PRODUCTOS[l.producto] },
    { criterio: 'Volumen', valor: l.volumen, puntos: VOLUMENES[l.volumen] },
    { criterio: 'Plazo', valor: l.plazo, puntos: PLAZOS[l.plazo] },
    { criterio: 'Sector', valor: l.sector, puntos: SECTORES[l.sector] },
  ];
  const puntos = desglose.reduce((a, d) => a + d.puntos, 0);
  const temperatura = l.producto === 'Otro producto' ? 'Fuera de catálogo' : puntos >= 70 ? 'Caliente' : puntos >= 40 ? 'Templado' : 'Frío';
  return { puntos, temperatura, desglose };
}
const estadoInicial = (t) => ({ Caliente: 'Nuevo', Templado: 'Nuevo', 'Frío': 'Boletín', 'Fuera de catálogo': 'Descartado' }[t]);
const horasParaLlamar = (t) => ({ Caliente: 24, Templado: 72 }[t] ?? 0);
const clave = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/,?\s*s\.?\s*[la]\.?$/, '').replace(/[^a-z0-9]/g, '');

// Leads de ejemplo de las dos últimas semanas, con fechas relativas a ahora y siempre los mismos para un mismo día.
// Son comunes a todos los visitantes y de solo lectura. Se puntúan con las mismas reglas que los del visitante.
const ahora = $now.setZone('Europe/Madrid').startOf('hour');
const LEADS = [
  // contacto, empresa, provincia, sector, producto, volumen, plazo, hace N horas, estado final (si ya lo tocó un comercial)
  ['Rubén Calvo', 'Instalaciones Solares Tajo, S.L.', 'Toledo', 'Estructuras metálicas', 'Perfiles para pladur', 'De 1.000 a 10.000 m al mes', 'Urgente (menos de 2 semanas)', 220, 'Contactado'],
  ['Marisa León', 'Reformas Guadalquivir, S.L.', 'Sevilla', 'Construcción', 'Corte a medida', 'Menos de 1.000 m al mes', 'Solo pido información', 190, 'Descartado'],
  ['Andoni Etxeberria', 'Estructuras Cantábrico, S.A.', 'Cantabria', 'Estructuras metálicas', 'Fleje de acero', 'De 1.000 a 10.000 m al mes', 'Este trimestre', 140, 'Recordatorio enviado'],
  ['Pilar Sanz', 'Carpintería Hermanos Sanz', 'Madrid', 'Otro', 'Otro producto', 'Menos de 1.000 m al mes', 'Solo pido información', 96],
  ['Unai Goñi', 'Taller Mecánico Irati', 'Navarra', 'Otro', 'Corte a medida', 'Menos de 1.000 m al mes', 'Solo pido información', 70],
  ['Vicent Ferrer', 'Almacenes Levante Construcción, S.L.', 'Valencia', 'Distribución de materiales', 'Perfiles para pladur', 'Menos de 1.000 m al mes', 'Solo pido información', 46],
  ['Teresa Gallego', 'Hormigones y Cubiertas Duero, S.L.', 'Valladolid', 'Construcción', 'Chapa perfilada para cubiertas', 'Más de 10.000 m al mes', 'Urgente (menos de 2 semanas)', 26, 'Contactado'],
  ['Jordi Bosch', 'Naves Agrícolas Ebro, S.L.', 'Zaragoza', 'Naves agrícolas', 'Chapa perfilada para cubiertas', 'De 1.000 a 10.000 m al mes', 'Este trimestre', 5],
];
return LEADS.map(([contacto, empresa, provincia, sector, producto, volumen, plazo, hace, final], i) => {
  const zona = zonaDe(provincia);
  const p = puntuar({ producto, volumen, plazo, sector });
  const llega = ahora.minus({ hours: hace }).set({ minute: (i * 13) % 60 });
  const horas = horasParaLlamar(p.temperatura);
  const decidido = final && final !== 'Recordatorio enviado';
  return { json: {
    sid: 'demo', fecha: llega.toFormat('yyyy-MM-dd HH:mm'), contacto, empresa, provincia, zona: zona[0], comercial: zona[1].comercial,
    sector, producto, volumen, plazo, mensaje: '', puntos: p.puntos, temperatura: p.temperatura, desglose: JSON.stringify(p.desglose),
    estado: final ?? estadoInicial(p.temperatura), llamar_antes: horas ? llega.plus({ hours: horas }).toFormat('yyyy-MM-dd HH:mm') : '',
    nota: final === 'Recordatorio enviado' ? 'Sin llamada en plazo: recordatorio al comercial y aviso a dirección' : '',
    decidido_en: decidido ? llega.plus({ hours: 3 + i }).toFormat('yyyy-MM-dd HH:mm') : '', creado_ms: 0,
  } };
});
